import {useModules} from '../../modules/context.tsx';
import React from 'react';
const kinds={plant:'埋设',progress:'推进',recover:'回收'};
const styles={solid:'实线',dashed:'虚线',dotted:'点线'};
const categories={other:'其他',family:'亲属',partner:'伙伴',enemy:'敌对',mentor:'师生',affiliation:'归属'};
export function StageChanges({stage,board,onMemory,onRelation,onShadow}){
 const modules=useModules();
 const changes=stage.changes,name=id=>board.nodes.find(n=>n.id===id)?.name||'已删除资料';
 if(!changes||!stage.event&&!changes.chapterForeshadows.length)return null;
 const label=v=>v.active?(v.name||categories[v.category]||'未命名关系'):'未生效';
 return <section className="story-changes" aria-label="本节点变化"><div className="story-section-title"><h3>{stage.event?'本节点变化':'本章记录'}</h3>{changes.planned&&<small>计划情境</small>}</div>{changes.entering.length>0&&<div className="story-change-entering"><small>首次进入故事 · 不等于正文出场</small><div className="story-material-chips">{changes.entering.map(n=><button key={n.id} onClick={()=>onMemory(n.id)}>{n.name}<em>{n.type==='character_card'?'人物':'世界'}</em></button>)}</div></div>}{modules.evolution&&changes.relationships.map(r=><button className={`story-change-relation kind-${r.kind}`} key={r.changeId} onClick={()=>onRelation({...board.edges.find(e=>e.id===r.edgeId),...r.after},stage.event)}><strong>{name(r.from)} → {name(r.to)}</strong><span>{label(r.before)} <b>→</b> {r.kind==='ended'?'关系结束':label(r.after)}</span>{r.before.category!==r.after.category&&<small>类别：{categories[r.before.category]} → {categories[r.after.category]}</small>}{r.before.style!==r.after.style&&<small>连线：{styles[r.before.style]} → {styles[r.after.style]}</small>}{r.contentChanged&&<small>说明已更新</small>}</button>)}{!changes.entering.length&&!changes.relationships.length&&stage.event&&<p className="story-empty-note">本节点没有记录资料进入或关系变化。</p>}{modules.foreshadow&&changes.chapterForeshadows.length>0&&<details className="story-change-shadows"><summary>本章伏笔依据 · {changes.chapterForeshadows.length}</summary><p>依据属于整章，不推断同章事件先后。</p>{changes.chapterForeshadows.map(f=><button key={f.id} onClick={()=>onShadow(f.id)}><strong>{f.title}</strong><small>{f.kinds.map(k=>kinds[k]).join(' · ')}{f.review?' · 待复核':''}</small></button>)}</details>}{modules.foreshadow&&changes.eventForeshadows.filter(f=>!changes.chapterForeshadows.some(x=>x.id===f.id)).length>0&&<div className="story-change-shadow-links"><small>事件关联伏笔</small>{modules.foreshadow&&changes.eventForeshadows.filter(f=>!changes.chapterForeshadows.some(x=>x.id===f.id)).map(f=><button key={f.id} onClick={()=>onShadow(f.id)}>{f.title}</button>)}</div>}</section>;
}
